{"command": "python3 -c "
import urllib.request
from html.parser import HTMLParser
import re

class BattingStatsParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_tbody = False
        self.in_row = False
        self.current_row = []
        self.rows = []
        self.in_cell = False
        self.current_cell = ''
        self.in_regular_player_section = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)

        # Check for the batting stats table
        if tag == 'table' and ('id', 'team_batting') in attrs:
            self.in_table = True
        elif tag == 'tbody' and self.in_table:
            self.in_tbody = True
        elif tag == 'tr' and self.in_tbody:
            # Check if this is a regular player row (not header, totals, etc.)
            if 'class' in attrs_dict:
                classes = attrs_dict['class'].split()
                if any(cls in classes for cls in ['thead', 'total_row', 'stat_total', 'sortable']):
                    return
            self.in_row = True
            self.current_row = []
        elif tag in ['th', 'td'] and self.in_row:
            self.in_cell = True
            self.current_cell = ''

    def handle_endtag(self, tag):
        if tag == 'td' and self.in_cell:
            self.in_cell = False
            self.current_row.append(self.current_cell.strip())
        elif tag == 'th' and self.in_cell:
            self.in_cell = False
            self.current_row.append(self.current_cell.strip())
        elif tag == 'tr' and self.in_row:
            self.in_row = False
            if self.current_row and len(self.current_row) > 10:  # Ensure it's a complete row
                self.rows.append(self.current_row)
        elif tag == 'tbody' and self.in_tbody:
            self.in_tbody = False
        elif tag == 'table' and self.in_table:
            self.in_table = False

    def handle_data(self, data):
        if self.in_cell:
            self.current_cell += data

try:
    # Fetch the page
    url = 'https://www.baseball-reference.com/teams/NYY/1977.shtml'
    headers = {'User-Agent': 'Mozilla/5.0 (compatible; stats_parser/1.0)'}

    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req) as response:
        html_content = response.read().decode('utf-8')

    # Parse the HTML
    parser = BattingStatsParser()
    parser.feed(html_content)

    # Process the rows to find player with highest walks
    max_walks_player = None
    max_walks = -1
    max_walks_at_bats = None

    for row in parser.rows:
        if len(row) >= 20:  # Ensure we have enough columns
            try:
                # Find player name (usually in first or second column)
                player_name = row[0] if row[0] and not row[0].isdigit() else row[1]

                # Find walks (BB) - usually around column 14-16
                walks = None
                at_bats = None

                # Look for BB column (walks)
                for i, cell in enumerate(row):
                    if i > 0:  # Skip player name column
                        # Try to parse as integer for stats
                        if cell.replace('.', '').isdigit():
                            # Check if this might be walks based on position (usually ~14th column)
                            if walks is None and i >= 13 and i <= 16:
                                walks = int(cell)
                            # At bats is usually around column 3-5
                            elif at_bats is None and i >= 2 and i <= 5:
                                at_bats = int(cell)

                if walks is not None and walks > max_walks:
                    max_walks = walks
                    max_walks_player = player_name
                    max_walks_at_bats = at_bats

            except (ValueError, IndexError):
                continue

    if max_walks_player:
        print(f'Player with highest walks: {max_walks_player}')
        print(f'Walks (BB): {max_walks}')
        print(f'At Bats (AB): {max_walks_at_bats}')
    else:
        print('Could not find player data')

except Exception as e:
    print(f'Error: {e}')
""}

