import urllib.request
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__()
        self.table_id = table_id
        self.in_target_table = False
        self.in_row = False
        self.in_cell = False
        self.current_row = []
        self.rows = []
        self.cell_data = []
        self.depth = 0

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)

        if tag == 'table':
            if ('id', self.table_id) in attrs:
                self.in_target_table = True
                self.depth = 1
        elif self.in_target_table:
            if tag in ['tr', 'td', 'th']:
                if tag == 'tr':
                    if not self.in_row:
                        self.in_row = True
                        self.current_row = []
                elif tag in ['td', 'th']:
                    if self.in_row:
                        self.in_cell = True
                        self.cell_data = []

    def handle_endtag(self, tag):
        if self.in_target_table:
            if tag == 'table':
                self.depth -= 1
                if self.depth == 0:
                    self.in_target_table = False
            elif tag in ['td', 'th']:
                if self.in_cell:
                    self.in_cell = False
                    cell_content = ''.join(self.cell_data).strip()
                    self.current_row.append(cell_content)
            elif tag == 'tr':
                if self.in_row:
                    self.in_row = False
                    if self.current_row:
                        self.rows.append(self.current_row)

    def handle_data(self, data):
        if self.in_cell:
            self.cell_data.append(data)

